const $=id=>document.getElementById(id);let data,live=false;async function json(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error('Report could not be saved');return r.json()}
try{try{const health=await json('/api/health');live=health.mode==='local_api';if(!live)throw Error();data=await json('/api/snapshot')}catch{data=await json('./data/snapshot.json')}$('driverStorage').textContent=live?'Connected to operations · reports are shared through this server.':'Snapshot mode · reports are stored only in this browser. For shared driver/manager reporting, use the local API deployment.';for(const r of data.routes){const o=new Option(`${r.route_code} ${r.direction} · ${r.origin} → ${r.terminus}`,r.id);$('driverRoute').add(o)}}catch(e){$('driverStorage').textContent='Route data is unavailable. Please reconnect before reporting.';$('submitReport').disabled=true}
$('driverRoute').onchange=()=>{const r=data.routes.find(r=>r.id===$('driverRoute').value);$('driverSection').replaceChildren(new Option('Whole route / not sure',''));if(r)for(const s of r.sections)$('driverSection').add(new Option(`${s.from_name} → ${s.to_name}`,s.id))};
$('driverForm').onsubmit=async e=>{e.preventDefault();$('submitReport').disabled=true;const row={route_id:$('driverRoute').value,section_id:$('driverSection').value,type:$('incidentType').value,description:$('description').value.trim()};try{if(live)await json('/api/incidents',row);else{const rows=JSON.parse(localStorage.getItem('marina-incidents')||'[]');rows.unshift({...row,id:crypto.randomUUID(),status:'reported',created_at:new Date().toISOString()});localStorage.setItem('marina-incidents',JSON.stringify(rows))}$('driverResult').hidden=false;$('driverResult').className='driver-success';$('driverResult').textContent=live?'Report saved. Operations can acknowledge and follow up.':'Report saved in this browser. It is not shared across devices in snapshot mode.';$('description').value=''}catch(e){$('driverResult').hidden=false;$('driverResult').textContent=e.message}finally{$('submitReport').disabled=false}};
